<?php
declare(strict_types=1); namespace App\Security\Voter; use App\Entity\User; use Symfony\Component\Security\Core\Authentication\Token\TokenInterface; use Symfony\Component\Security\Core\Authorization\Voter\Voter; final class UserVoter extends Voter {public const VIEW='USER_VIEW';public const BULK_ACTIVATE='USER_BULK_ACTIVATE';public const BULK_DEACTIVATE='USER_BULK_DEACTIVATE';protected function supports(string $a,mixed $s):bool{return $s instanceof User&&in_array($a,[self::VIEW,self::BULK_ACTIVATE,self::BULK_DEACTIVATE],true);} protected function voteOnAttribute(string $a,mixed $s,TokenInterface $t):bool{$u=$t->getUser();if(!$u instanceof User||!$u->isActive()||$u->isDeleted()||$s->isDeleted())return false;if(in_array('ROLE_ADMIN',$u->getRoles(),true))return true;return $a===self::VIEW&&$u->getId()===$s->getId();}}
